param([string]$BaseDir = ".")
$ErrorActionPreference = "Stop"
function Assert-Eq($A,$E,[string]$L){if([string]$A-ne[string]$E){throw "$L mismatch: actual=$A expected=$E"}}
function Parse-Pairs([string]$Line,[string]$Prefix,[int]$Start=1){$f=$Line-split"`t";if($f[0]-ne$Prefix-or(($f.Count-$Start)%2)-ne0){throw"malformed $Prefix: $Line"};$h=@{};for($i=$Start;$i-lt$f.Count;$i+=2){if($h.ContainsKey($f[$i])){throw"duplicate $($f[$i])"};$h[$f[$i]]=$f[$i+1]};return$h}
function Load-Map([string]$Name,[bool]$Sol){$m=@{};foreach($l in[IO.File]::ReadAllLines((Join-Path$BaseDir $Name))){if($l-notmatch'^ENTRY\t24T([0-9]+)\t'){continue};$k=[int]$Matches[1];$f=$l-split"`t";$h=@{};for($i=2;$i-lt$f.Count;$i+=2){$h[$f[$i]]=$f[$i+1]};$m[$k]=[pscustomobject]@{Order=[int64]$h.ORDER;Parity=[int64]$h.PARITY_MAPS;Solvable=if($Sol){[int]$h.SOLVABLE}else{$null}}};return$m}
function Keys($M,[int]$Lo,[int]$Hi){return@($M.Keys|%{[int]$_}|?{$_-ge$Lo-and$_-le$Hi}|Sort-Object)}
function Parse-Entry([string]$L){$f=$L-split"`t";if($f[0]-ne'ENTRY'-or$f[1]-notmatch'^24T([0-9]+)$'-or(($f.Count-2)%2)-ne0){throw"bad ENTRY: $L"};$k=[int]$Matches[1];$h=@{};for($i=2;$i-lt$f.Count;$i+=2){$h[$f[$i]]=$f[$i+1]};foreach($n in@('ORDER','SOLVABLE_G','PARITY_MAPS_G','PC_ORDER','PARITY_MAPS_P','AUT_ORDER','ISO_MS','AUT_MS','METHOD','CLASS_MS','ORDER8_CLASSES','RAW_PAIRS')){if(-not$h.ContainsKey($n)){throw"24T$k missing $n"}};return[pscustomobject]@{K=$k;Order=[int64]$h.ORDER;Solvable=$h.SOLVABLE_G;Parity=[int64]$h.PARITY_MAPS_G;PcOrder=[int64]$h.PC_ORDER;ParityP=[int64]$h.PARITY_MAPS_P;AutOrder=$h.AUT_ORDER;Iso=[int64]$h.ISO_MS;Aut=[int64]$h.AUT_MS;Method=$h.METHOD;Class=[int64]$h.CLASS_MS;Classes=[int64]$h.ORDER8_CLASSES;Raw=[int64]$h.RAW_PAIRS;Line=$L}}
$lo=12333;$hi=12595;$outName='GAP_TRANSITIVE_DEGREE24_AUT_PROFILE_12333_12595_PC_DOMAIN_RECOVERY_CHECKPOINT_GPT56SOL.txt';$stdoutName='GAP_TRANSITIVE_DEGREE24_AUT_PROFILE_SHARD14_RUN_STDOUT_GPT56SOL.txt';$stderrName='GAP_TRANSITIVE_DEGREE24_AUT_PROFILE_SHARD14_RUN_STDERR_GPT56SOL.txt';$wrapper='gap_run_degree24_aut_profile_shard14_12333_12595_pc_domain_gpt56sol.g'
