Assert-Eq @($lines|?{$_-match'^TOTAL\t'}).Count 1 'TOTAL count';Assert-Eq @($lines|?{$_-eq'DONE'}).Count 1 'DONE count';Assert-Eq $lines[-1] 'DONE' 'terminal';Assert-Eq @($lines|?{$_-match'^(TOTAL_PARTIAL|STOPPED_GUARD)'}).Count 0 'guard markers'
$entries=@();for($i=0;$i-lt$lines.Count;$i++){if($lines[$i]-match'^ENTRY\t'){$entries+=Parse-Entry $lines[$i]}};Assert-Eq $entries.Count 256 'entry count';Assert-Eq @($entries|Group-Object K|?{$_.Count-ne1}).Count 0 'duplicates';Assert-Eq @(Compare-Object $expected @($entries.K)).Count 0 'entry keyset'
