$scanKeys=@(12350,12375,12400,12425,12450,12475,12500,12525,12550,12575);$scans=@($lines|?{$_-match'^SCAN_CHECKPOINT\t'});Assert-Eq $scans.Count 10 'scan count';for($j=0;$j-lt10;$j++){$h=Parse-Pairs $scans[$j] 'SCAN_CHECKPOINT';$k=$scanKeys[$j];$p=@($entries|?{$_.K-le$k});Assert-Eq $h.LAST_COMPLETE_K $k 'scan key';Assert-Eq $h.ORDER_WINDOW (Keys $win $lo $k).Count 'scan window';Assert-Eq $h.PROCESSED $p.Count 'scan processed';Assert-Eq $h.ISO_MS ([int64](($p|Measure-Object Iso -Sum).Sum)) 'scan iso';Assert-Eq $h.ORDER8_CLASSES ([int64](($p|Measure-Object Classes -Sum).Sum)) 'scan classes';Assert-Eq $h.RAW_PAIRS ([int64](($p|Measure-Object Raw -Sum).Sum)) 'scan raw'}
