Assert-Eq $classes 6265 'outcome classes';Assert-Eq $raw 123526656 'outcome raw';Assert-Eq $iso 222 'outcome iso';Assert-Eq $aut 73564 'outcome aut';Assert-Eq $class 77093 'outcome class';Assert-Eq $gapMs 158727 'outcome gap'
$stdout=[IO.File]::ReadAllText((Join-Path$BaseDir $stdoutName));$stderr=[IO.File]::ReadAllText((Join-Path$BaseDir $stderrName));Assert-Eq $stdout.Trim() "WROTE /mnt/d/work/revise/production_code/escalations/$outName" 'stdout';if($stderr-notmatch[regex]::Escape($wrapper)){throw'missing wrapper telemetry'};if($stderr-notmatch'Elapsed \(wall clock\) time \(h:mm:ss or m:ss\): ([^\r\n]+)'){throw'missing wall'};$wall=$Matches[1].Trim();Assert-Eq $wall '2:39.89' 'wall';if($stderr-notmatch'Maximum resident set size \(kbytes\): ([0-9]+)'){throw'missing RSS'};$rss=[int64]$Matches[1];Assert-Eq $rss 182400 'RSS';if($stderr-notmatch'Exit status: 0'){throw'bad exit'};if($rss-ge50331648){throw'RSS guard exceeded'}
